mapper.select:
SELECT * FROM ( SELECT a.*, ROWNUM rnum FROM ( SELECT b.board_id as boardId, b.member_id as memberId, b.board_type as boardType, b.title as title, b.content as content, b.hit as hit, b.created_at as createdAt, m.nickname as writerNickname, m.membership as writerMembership, m.role as writerRole, (SELECT CASE WHEN COUNT(*) > 0 THEN '답변완료' ELSE '답변대기' END FROM board_comment bc JOIN shop_member sm ON bc.member_id = sm.member_id WHERE bc.board_id = b.board_id AND sm.role = 'ADMIN') as replyStatus FROM board b JOIN shop_member m ON b.member_id = m.member_id
b.board_type = #{boardType}
AND b.title LIKE '%' || #{keyword} || '%' AND b.content LIKE '%' || #{keyword} || '%'
AND (b.title LIKE '%' || #{keyword} || '%' OR b.content LIKE '%' || #{keyword} || '%')
AND m.nickname LIKE '%' || #{keyword} || '%'
ORDER BY CASE WHEN b.board_type = 'NOTICE' THEN 1 ELSE 2 END ASC, b.created_at DESC ) a WHERE ROWNUM <= #{endRow} ) WHERE rnum > #{offset}

