mapper.update:
UPDATE board
SET title = #{title}, content = #{content}, updated_at = SYSDATE

    , image_name = #{imageName, jdbcType=VARCHAR}, image_path = #{imagePath, jdbcType=VARCHAR}
    , image_name_2 = #{imageName2, jdbcType=VARCHAR}, image_path_2 = #{imagePath2, jdbcType=VARCHAR}
    , image_name_3 = #{imageName3, jdbcType=VARCHAR}, image_path_3 = #{imagePath3, jdbcType=VARCHAR}

WHERE board_id = #{boardId}
